import{_ as o,o as r,c as l,ag as n}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"다른 논쟁들과의 차이점","slug":"다른-논쟁들과의-차이점","link":"#다른-논쟁들과의-차이점","children":[]},{"level":2,"title":"핵심 쟁점 넷","slug":"핵심-쟁점-넷","link":"#핵심-쟁점-넷","children":[{"level":3,"title":"1. 지각논변 — 지각은 심(心)의 작용인가, 지(智)의 작용인가?","slug":"_1-지각논변-—-지각은-심-心-의-작용인가-지-智-의-작용인가","link":"#_1-지각논변-—-지각은-심-心-의-작용인가-지-智-의-작용인가","children":[]},{"level":3,"title":"2. 인물성동이논변 — 인간과 동물의 본성은 같은가, 다른가?","slug":"_2-인물성동이논변-—-인간과-동물의-본성은-같은가-다른가","link":"#_2-인물성동이논변-—-인간과-동물의-본성은-같은가-다른가","children":[]},{"level":3,"title":"3. 미발논변 — 미발심체는 순선한가, 그렇지 않은가?","slug":"_3-미발논변-—-미발심체는-순선한가-그렇지-않은가","link":"#_3-미발논변-—-미발심체는-순선한가-그렇지-않은가","children":[]},{"level":3,"title":"4. 성범심동이논변 — 성인의 마음과 일반인의 마음은 같은가, 다른가?","slug":"_4-성범심동이논변-—-성인의-마음과-일반인의-마음은-같은가-다른가","link":"#_4-성범심동이논변-—-성인의-마음과-일반인의-마음은-같은가-다른가","children":[]}]},{"level":2,"title":"요약: 두 진영의 입장","slug":"요약-두-진영의-입장","link":"#요약-두-진영의-입장","children":[]}],"relativePath":"philosophy/Korean-Philosophy/11. 호락논쟁.md","filePath":"philosophy/Korean-Philosophy/11. 호락논쟁.md"}'),e={name:"philosophy/Korean-Philosophy/11. 호락논쟁.md"};function a(s,t,i,d,g,h){return r(),l("div",null,[...t[0]||(t[0]=[n('<blockquote><p>이 강의 역시 시험 범위에서 제외된다고 표시되어 있으나(&quot;시험x&quot;), 조선 후기 성리학 논쟁의 중요한 축이므로 정리해둠.</p></blockquote><h2 id="다른-논쟁들과의-차이점" tabindex="-1">다른 논쟁들과의 차이점 <a class="header-anchor" href="#다른-논쟁들과의-차이점" aria-label="Permalink to &quot;다른 논쟁들과의 차이점&quot;">​</a></h2><p><strong>무극태극논쟁</strong>, <strong>사단칠정논쟁</strong>, <strong>인심도심논쟁</strong>은 모두 논쟁의 주제로 이름이 붙었지만, <strong>호락논쟁</strong>은 특이하게 논쟁의 <strong>주체</strong>(호론·낙론)로 이름이 붙었다. 이는 호락논쟁의 쟁점이 단 하나가 아니기 때문이다. 가장 널리 알려진 것은 <strong>인물성동이논쟁</strong>(인간과 동물의 본성이 같은가 다른가)이지만, 이 논쟁 전체를 관통하는 더 근본적인 질문은 <strong>&quot;인간의 심성이 태생적 오염으로부터 얼마나 자유로울 수 있는가&quot;</strong>, 즉 <strong>미발심선악유무</strong>(未發心善惡有無) 문제다.</p><p>주자학에 따르면 누구나 한 점의 오염도 없는 순선한 천리를 본성으로 갖고 태어나며(성선설), 따라서 누구나 노력하면 성인이 될 수 있다. 그런데 현실에서는 어떤 사람은 성인처럼 살고 어떤 사람은 그렇지 않다 — 그 차이는 타고난 <strong>기질</strong>의 차이 때문이라는 것이 표준적 설명이다(주자: &#39;기질의 구애와 인욕의 엄폐&#39;). 그렇다면 외부 사물과 접촉하기 전, 즉 <strong>미발(未發)</strong> 상태에서는 어떨까? 왜곡된 욕망이 발생할 계기가 없으니 원론적으로는 성인과 보통 사람 사이에 차이가 없어야 할 것 같지만, 문제는 그리 간단하지 않다 — 오염된 기질 자체는 애초에 타고난 것이므로, 태어날 때 이미 오염된 기질을 가지고 있다고 볼 수도 있기 때문이다. 이 지점에서 <strong>호론</strong>과 <strong>낙론</strong>이 갈린다.</p><ul><li><strong>호론</strong>(권상하·한원진·윤봉구 등): 기질에 의한 오염은 미발·이발을 막론하고 상존하므로, 미발 시에도 인간의 심성에 악이 존재할 수 있으며 성인과 보통 사람 사이에 차이가 있다.</li><li><strong>낙론</strong>(김창협·이재·이간 등): 미발 시에는 오염된 기질이 완전히 숨어 있어 선한 본성과 마음을 가리지 않으므로, 미발 시에는 오직 선함만 있고 성인과 보통 사람의 차이도 없다.</li></ul><h2 id="핵심-쟁점-넷" tabindex="-1">핵심 쟁점 넷 <a class="header-anchor" href="#핵심-쟁점-넷" aria-label="Permalink to &quot;핵심 쟁점 넷&quot;">​</a></h2><h3 id="_1-지각논변-—-지각은-심-心-의-작용인가-지-智-의-작용인가" tabindex="-1">1. 지각논변 — 지각은 심(心)의 작용인가, 지(智)의 작용인가? <a class="header-anchor" href="#_1-지각논변-—-지각은-심-心-의-작용인가-지-智-의-작용인가" aria-label="Permalink to &quot;1. 지각논변 — 지각은 심(心)의 작용인가, 지(智)의 작용인가?&quot;">​</a></h3><p>마음은 인간의 지각기관으로서 한 몸의 주인이 되어 만물에 반응한다. 형기의 사사로움에서 발생하는 것이 인심, 의리의 공정함에서 발생하는 것이 도심이라는 구도(『주자대전』)는 앞서 인심도심논쟁에서와 같다. 성리학에서 &#39;지각&#39;은 단순한 감각이 아니라, 실제로 보고 듣고 생각하고 느끼는 작용이자 그것을 가능하게 하는 능력·매체·수행자를 함께 가리키는 개념이다.</p><ul><li><strong>낙론</strong>(김창협·이현익 등): 지각은 마음의 본질적 성격인 <strong>허령함</strong>(알아차리는 능력)이 작용한 것이고, 지(智)는 성(性)에 자리한 도덕규범이다. 지각은 어디까지나 심(心) 쪽의 문제이며, 지는 그 위에 놓인 리의 층위다 — 마음을 인식주체로 다루는 관점.</li><li><strong>호론</strong>(권상하·한원진 등): 지각은 단순한 동물적 감각이 아니라 본성인 지(智)의 덕성이 발휘된 것이다. 따라서 지각의 주재성과 도덕성은 심이 아니라 본성인 지에 귀속된다.</li></ul><h3 id="_2-인물성동이논변-—-인간과-동물의-본성은-같은가-다른가" tabindex="-1">2. 인물성동이논변 — 인간과 동물의 본성은 같은가, 다른가? <a class="header-anchor" href="#_2-인물성동이논변-—-인간과-동물의-본성은-같은가-다른가" aria-label="Permalink to &quot;2. 인물성동이논변 — 인간과 동물의 본성은 같은가, 다른가?&quot;">​</a></h3><p>주자학은 성(性)을 <strong>본연지성</strong>(本然之性, 一理)과 <strong>기질지성</strong>(氣質之性, 分殊之理) 두 차원으로 나눈다 — &quot;리를 말하면 온전하지 않은 데가 없지만, 성을 말하면 온전한 것과 편벽된 것이 있다.&quot;</p><ul><li><strong>낙론</strong>: 성은 기질적 제약을 초월한 보편적 본체다. 따라서 인간이든 동물이든 &#39;본연지성&#39; 차원에서는 같으며, 동물도 일정한 의미의 도덕성을 가진다. 다만 인간은 그 도덕성을 온전히 구현할 수 있는 기질을 가진 반면 동물은 그렇지 못하다.</li><li><strong>호론</strong>: 성은 실제로는 기질을 떠나 존재하지 않으며, 기질에 의해 개체적으로 규정된다. 따라서 인간과 동물의 성은 실질적으로 다르며, 나아가 인간 중에서도 중화인과 오랑캐 사이에 본성의 차이가 있다.</li></ul><h3 id="_3-미발논변-—-미발심체는-순선한가-그렇지-않은가" tabindex="-1">3. 미발논변 — 미발심체는 순선한가, 그렇지 않은가? <a class="header-anchor" href="#_3-미발논변-—-미발심체는-순선한가-그렇지-않은가" aria-label="Permalink to &quot;3. 미발논변 — 미발심체는 순선한가, 그렇지 않은가?&quot;">​</a></h3><p>미발 문제는 &#39;<strong>치중화</strong>(致中和, 중화를 이룸)&#39;라는 수양론적 목표와 밀접하다 — &quot;희로애락이 아직 발하지 않은 것을 중(中)이라 하고, 발하여 모두 절도에 맞는 것을 화(和)라 한다. 중화를 이루면 천지가 제자리를 잡고 만물이 길러진다&quot;(『중용』). 미발의 상태를 표현하는 대표적 용어는 <strong>&#39;사려미맹&#39;</strong>(思慮未萌, 사려가 아직 싹트지 않은 상태)과 <strong>&#39;지각불매&#39;</strong>(知覺不昧, 지각이 어둡지 않은 상태)인데, 언뜻 서로 충돌하는 것처럼 보이는 이 두 개념을 조화롭게 해석하는 것이 논쟁의 실마리가 됨.</p><ul><li><strong>낙학의 쟁점</strong>: 미발에서 공부(수양)를 할 수 있는가, 해야 하는가, 애초에 &#39;공부&#39;라는 말이 성립하는가? — 이현익은 미발이 최상의 경지이므로 공부가 불가능·불필요하다고 본 반면, 김창흡은 미발을 &#39;중/부중&#39;으로 나누어 겉으로는 고요해도 흐트러짐이 스며든 &#39;부중의 미발&#39;에는 계신공구(戒愼恐懼)가 필요하다고 절충함.</li><li><strong>호학의 쟁점</strong>: 미발에서 기질지성을 논하는 것이 가능한가? — 초기에는 &quot;미발은 본연지성의 자리, 이발은 기질지성이 끼어드는 자리&quot;로 보았으나, <strong>한원진</strong>은 이것이 &#39;성발위정&#39;의 논리에 어긋난다고 지적함 — 현실에 존재하는 모든 성은 언제나 기질과 얽혀 있으므로, 기질지성을 떠난 &#39;본연지성&#39;이란 공허한 추상에 불과하다는 것. 이에 <strong>이재</strong>는 미발심을 순선한 본연지성의 자리로 보지 않으면 맹자의 성선론, 즉 누구나 성인이 될 수 있다는 주장의 기반 자체가 흔들린다고 반박함.</li></ul><h3 id="_4-성범심동이논변-—-성인의-마음과-일반인의-마음은-같은가-다른가" tabindex="-1">4. 성범심동이논변 — 성인의 마음과 일반인의 마음은 같은가, 다른가? <a class="header-anchor" href="#_4-성범심동이논변-—-성인의-마음과-일반인의-마음은-같은가-다른가" aria-label="Permalink to &quot;4. 성범심동이논변 — 성인의 마음과 일반인의 마음은 같은가, 다른가?&quot;">​</a></h3><p>인물성동이논변이 &#39;본성&#39;을 다룬다면 성범심동이논변은 &#39;마음&#39;을 다룬다. 미발 상태에서 성인과 일반인의 마음에 차이를 말할 수 있는가? 부여받은 기질의 편차와 수양 여부에 따라 미발 상태에도 어떤 차이가 있다고 해야 하지 않을까? 논쟁 후기(3기)에는 이것이 **명덕(明德)**에 관한 문제로 확장됨 — 명덕이 결국 부여된 기(정밀하고 텅 비고 신령한 기)의 성격에 의해 가능해진 것이라면, 명덕에도 기질의 편차(따라서 성인과 일반인의 인지적·실천적 능력 차이)를 말할 수 있는 것 아니냐는 의심이 낙학 측에서 제기되며 쟁점화됨.</p><h2 id="요약-두-진영의-입장" tabindex="-1">요약: 두 진영의 입장 <a class="header-anchor" href="#요약-두-진영의-입장" aria-label="Permalink to &quot;요약: 두 진영의 입장&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>낙론계 (성/리 중심 보편주의)</th><th>호론계 (심/기질 중심 현실주의)</th></tr></thead><tbody><tr><td>인물성동이</td><td>성즉리를 밀면 본연지성 차원에서 만물이 두루 통함 — 동론(同論)</td><td>성은 실제로 기질과 얽혀 있고, 인간과 동물의 기질이 다름 — 이론(異論)</td></tr><tr><td>미발시 선악</td><td>본연지성이 온전히 갖추어진 중(中)이므로 순선</td><td>성은 언제나 기질 위에서만 존재하므로 미발심체에도 선악이 공존</td></tr><tr><td>미발시 공부</td><td>논리적 미발시엔 불가능, 실질적 미발시엔 가능</td><td>미발시에도 기질지성을 다듬고 바로잡는 공부가 필요</td></tr><tr><td>성범심</td><td>본연지성 관점에서 동일</td><td>기질지성 관점에서 다름</td></tr></tbody></table>',19)])])}const c=o(e,[["render",a]]);export{_ as __pageData,c as default};
